// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

/**
* Interface describing `dlarnv`.
*/
interface Routine {
	/**
	* Returns a vector of `n` random real numbers from a uniform or normal distribution.
	*
	* @param idist - distribution type: 1=uniform(0,1), 2=uniform(-1,1), 3=normal(0,1)
	* @param iseed - seed array of four integers
	* @param n - number of random numbers to generate
	* @param x - output array
	* @returns output array
	*
	* @example
	* var Int32Array = require( '@stdlib/array/int32' );
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var iseed = new Int32Array( [ 0, 1, 2, 3 ] );
	* var x = new Float64Array( 5 );
	*
	* dlarnv( 1, iseed, 5, x );
	* // x => <Float64Array>
	*/
	( idist: number, iseed: Int32Array, n: number, x: Float64Array ): Float64Array;

	/**
	* Returns a vector of `n` random real numbers from a uniform or normal distribution using alternative indexing semantics.
	*
	* @param idist - distribution type: 1=uniform(0,1), 2=uniform(-1,1), 3=normal(0,1)
	* @param iseed - seed array of four integers
	* @param strideIseed - stride length for `iseed`
	* @param offsetIseed - starting index for `iseed`
	* @param n - number of random numbers to generate
	* @param x - output array
	* @param strideX - stride length for `x`
	* @param offsetX - starting index for `x`
	* @returns output array
	*
	* @example
	* var Int32Array = require( '@stdlib/array/int32' );
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var iseed = new Int32Array( [ 0, 1, 2, 3 ] );
	* var x = new Float64Array( 5 );
	*
	* dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1, 0 );
	* // x => <Float64Array>
	*/
	ndarray( idist: number, iseed: Int32Array, strideIseed: number, offsetIseed: number, n: number, x: Float64Array, strideX: number, offsetX: number ): Float64Array;
}

/**
* Returns a vector of `n` random real numbers from a uniform or normal distribution.
*
* @param idist - distribution type: 1=uniform(0,1), 2=uniform(-1,1), 3=normal(0,1)
* @param iseed - seed array of four integers
* @param n - number of random numbers to generate
* @param x - output array
* @returns output array
*
* @example
* var Int32Array = require( '@stdlib/array/int32' );
* var Float64Array = require( '@stdlib/array/float64' );
*
* var iseed = new Int32Array( [ 0, 1, 2, 3 ] );
* var x = new Float64Array( 5 );
*
* dlarnv( 1, iseed, 5, x );
* // x => <Float64Array>
*
* @example
* var Int32Array = require( '@stdlib/array/int32' );
* var Float64Array = require( '@stdlib/array/float64' );
*
* var iseed = new Int32Array( [ 0, 1, 2, 3 ] );
* var x = new Float64Array( 5 );
*
* dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1, 0 );
* // x => <Float64Array>
*/
declare var dlarnv: Routine;


// EXPORTS //

export = dlarnv;
